import { useMemo, useState } from 'react'

/**
 * The catalogue, drawn to one scale.
 *
 * This is the only section whose content cannot be written, only read
 * off the registry: generated by `tools/probe-catalogue.ts`, so it
 * cannot drift from the product by being edited here. Re-run it when
 * the catalogue changes.
 *
 * Every tile carries the part in elevation at one shared scale — the
 * same millimetres-per-pixel for all thirty-two of them — which is the
 * entire argument of the section made as a drawing rather than as a
 * sentence. At this scale a wall socket is a chip you can barely see
 * and a door fills its tile, and that is the honest relationship
 * between the two. A catalogue where every thumbnail is the same size
 * is a catalogue of icons, and an icon is exactly the thing this
 * product refuses to place in a room.
 *
 * The scale is set by the largest thing in the list rather than chosen,
 * so adding something bigger shrinks everything else instead of
 * quietly clipping.
 */

interface Part {
  name: string
  where: string
  /** Millimetres: width, height, depth. */
  w: number
  h: number
  d: number
}

const SHELF: Part[] = [
  { name: 'Room', where: 'Rooms & openings', w: 4310, h: 2420, d: 3710 },
  { name: 'Projection screen', where: 'Screens & projection', w: 2777, h: 1614, d: 22 },
  { name: 'Cinema seating', where: 'Seating & theatre', w: 2950, h: 1185, d: 900 },
  { name: 'Surround speaker', where: 'Speakers & audio', w: 280, h: 1310, d: 300 },
  { name: 'AV receiver', where: 'Screens & projection', w: 434, h: 170, d: 396 },
  { name: 'Projector', where: 'Screens & projection', w: 244, h: 101, d: 203 },
  { name: 'Seating riser', where: 'Seating & theatre', w: 4000, h: 308, d: 2500 },
  { name: 'Desk', where: 'Furniture', w: 1400, h: 740, d: 700 },
  { name: 'Desktop monitor', where: 'Screens & projection', w: 606, h: 481, d: 190 },
  { name: 'Task chair', where: 'Furniture', w: 680, h: 1030, d: 680 },
  { name: 'Rug', where: 'Finish & decor', w: 2000, h: 9, d: 1400 },
  { name: 'Potted plant', where: 'Finish & decor', w: 382, h: 489, d: 354 },
  { name: 'Acoustic panel', where: 'Finish & decor', w: 600, h: 600, d: 50 },
  { name: 'Network rack', where: 'Network', w: 553, h: 460, d: 460 },
  { name: 'NAS', where: 'Network', w: 158, h: 180, d: 235 },
  { name: 'Wireless access point', where: 'Network', w: 176, h: 37, d: 176 },
  { name: '3D printer', where: 'Soldering & fabrication', w: 440, h: 436, d: 376 },
  { name: 'Oscilloscope', where: 'Test & measurement', w: 360, h: 180, d: 142 },
  { name: 'Soldering station', where: 'Soldering & fabrication', w: 313, h: 150, d: 167 },
  { name: 'Studio monitor', where: 'Speakers & audio', w: 173, h: 280, d: 208 },
  { name: 'Condenser microphone', where: 'Speakers & audio', w: 102, h: 166, d: 102 },
  { name: 'Television', where: 'Screens & projection', w: 1228, h: 765, d: 240 },
  { name: 'Soundbar', where: 'Screens & projection', w: 950, h: 62, d: 112 },
  { name: 'Desktop PC', where: 'Computers & consoles', w: 216, h: 460, d: 463 },
  { name: 'PlayStation 5', where: 'Computers & consoles', w: 104, h: 390, d: 266 },
  { name: 'Extension lead', where: 'Mains & sockets', w: 306, h: 52, d: 36 },
  { name: 'Wall socket', where: 'Mains & sockets', w: 146, h: 86, d: 14 },
  { name: 'Fan heater', where: 'Mains & sockets', w: 230, h: 252, d: 156 },
  { name: 'Door', where: 'Rooms & openings', w: 826, h: 2013, d: 513 },
  { name: 'Window', where: 'Rooms & openings', w: 1360, h: 1290, d: 190 },
  { name: 'Wall shelf', where: 'Finish & decor', w: 900, h: 182, d: 240 },
  { name: 'COB LED strip', where: 'Lighting', w: 3000, h: 2, d: 10 },
]

/** The widest tile a part may draw into, in pixels. */
const BAY = 170
/** Tall enough for the tallest thing at the scale the widest thing sets. */
const BAY_H = 100

const PX = Math.min(BAY / Math.max(...SHELF.map((p) => p.w)), BAY_H / Math.max(...SHELF.map((p) => p.h)))

/** The part in elevation, at the one scale, standing on the tile floor. */
function Elevation({ p }: { p: Part }) {
  /* A hairline, not nothing: a 2 mm LED strip and a 9 mm rug are real
     objects whose height rounds to zero at any scale that also fits a
     room on the page. Drawing them at half a pixel would be drawing
     nothing, which would be a worse lie than drawing them at one. */
  const w = Math.max(1, p.w * PX)
  const h = Math.max(1, p.h * PX)
  return (
    <svg width={w} height={h} viewBox={`0 0 ${w} ${h}`} aria-hidden="true">
      <rect x={0.5} y={0.5} width={Math.max(0.5, w - 1)} height={Math.max(0.5, h - 1)} />
    </svg>
  )
}

export function Shelf() {
  const [q, setQ] = useState('')

  const shown = useMemo(() => {
    const needle = q.trim().toLowerCase()
    if (!needle) return SHELF
    return SHELF.filter(
      (p) => p.name.toLowerCase().includes(needle) || p.where.toLowerCase().includes(needle),
    )
  }, [q])

  return (
    <>
      <div className="dr-shelf-top">
        <div className="dr-sec-head">
          <h2>Parts library</h2>
          <p>32 of 266, drawn in elevation to one scale.</p>
        </div>

        <div className="dr-find">
          <svg width="15" height="15" viewBox="0 0 15 15" fill="none" stroke="currentColor" strokeWidth="1.4" aria-hidden="true">
            <circle cx="6.5" cy="6.5" r="4.6" />
            <path d="M10 10 L14 14" />
          </svg>
          <input
            type="search"
            value={q}
            onChange={(e) => setQ(e.target.value)}
            placeholder="Filter the catalogue"
            aria-label="Filter the catalogue"
          />
          <span className="n">
            {shown.length}/{SHELF.length}
          </span>
        </div>
      </div>

      <div className="dr-shelf-grid">
        {shown.map((p) => (
          <div className="dr-item" key={p.name}>
            <span className="dr-item-fig">
              <Elevation p={p} />
            </span>
            <strong>{p.name}</strong>
            <span>{p.where}</span>
            <span className="m">
              {p.w} × {p.h} × {p.d} mm
            </span>
          </div>
        ))}
        {shown.length === 0 && (
          <p className="dr-shelf-none">
            Nothing in the catalogue matches “{q.trim()}”. There are six sections and
            thirty-two parts; try a room, a screen or a socket.
          </p>
        )}
      </div>
    </>
  )
}
